int diameter(TreeNode* root) {
    int best = 0;
    std::function<int(TreeNode*)> depth = [&](TreeNode* n) -> int {
        if (!n) return 0;
        int l = depth(n->left);
        int r = depth(n->right);
        best = std::max(best, l + r);
        return 1 + std::max(l, r);
    };
    depth(root);
    return best;
}
